#!/usr/bin/env python3
# Original clean-room reimplementation for the benchmark.
# It implements the LuaJIT command line plus a practical Lua 5.1 interpreter subset.

import sys, os, math as _math, time as _time, random as _random, re, subprocess, tempfile, locale, traceback as _pytrace
from collections import OrderedDict
from dataclasses import dataclass

VERSION = "LuaJIT 2.1.1772570160"
VERSION_LINE = VERSION + " -- Copyright (C) 2005-2026 Mike Pall. https://luajit.org/"
LUA_VERSION = "Lua 5.1"
DEFAULT_PATH = "./?.lua;/usr/local/share/luajit-2.1/?.lua;/usr/local/share/lua/5.1/?.lua;/usr/local/share/lua/5.1/?/init.lua"
DEFAULT_CPATH = "./?.so;/usr/local/lib/lua/5.1/?.so;/usr/local/lib/lua/5.1/loadall.so"
PACKAGE_CONFIG = "/\n;\n?\n!\n-\n"

class NilType:
    def __bool__(self): return False
    def __repr__(self): return 'nil'

nil = NilType()

class LuaError(Exception):
    def __init__(self, msg, line=None, source=None, add_location=True):
        super().__init__(str(msg))
        self.msg = str(msg)
        self.line = line
        self.source = source
        self.add_location = add_location

class LuaExit(BaseException):
    def __init__(self, code=0): self.code = code

class LuaReturn(Exception):
    def __init__(self, vals): self.vals = vals

class LuaBreak(Exception):
    pass

class LuaSyntax(Exception):
    def __init__(self, msg, line=1):
        super().__init__(msg); self.msg=msg; self.line=line

# --- Lua values -----------------------------------------------------------

def is_nil(v): return v is nil

def truthy(v): return not (v is nil or v is False)

def is_num(v): return (isinstance(v, (int, float)) and not isinstance(v, bool))

def number_value(v):
    if is_num(v): return v
    if isinstance(v, str):
        n = parse_lua_number(v.strip(), silent=True)
        if n is not None: return n
    raise LuaError("attempt to perform arithmetic on a %s value" % lua_type(v))

def lua_type(v):
    if v is nil: return 'nil'
    if isinstance(v, bool): return 'boolean'
    if is_num(v): return 'number'
    if isinstance(v, str): return 'string'
    if isinstance(v, LuaTable): return 'table'
    if isinstance(v, (LuaFunction, BuiltinFunction)): return 'function'
    if isinstance(v, LuaThread): return 'thread'
    if isinstance(v, (LuaFile, CData, CLib)): return 'userdata' if not isinstance(v, CData) else 'cdata'
    return 'userdata'

def format_number(n):
    if isinstance(n, bool): return 'true' if n else 'false'
    if isinstance(n, int): return str(n)
    if isinstance(n, float):
        if _math.isnan(n): return 'nan'
        if _math.isinf(n): return 'inf' if n > 0 else '-inf'
        # LuaJIT's tostring uses a compact %.14g-like representation.
        s = ("%.14g" % n)
        if s == '-0': s = '0'
        # Python emits e-05, LuaJIT too for observed values.
        return s
    return str(n)

def normalize_number(n):
    if isinstance(n, bool): return n
    if isinstance(n, float) and n.is_integer() and abs(n) < (1<<63):
        return int(n)
    return n

def key_id(k):
    if k is nil:
        raise LuaError("table index is nil")
    if isinstance(k, bool): return ('bool', k)
    if is_num(k):
        if isinstance(k, float) and _math.isnan(k): raise LuaError("table index is NaN")
        return ('num', float(k))
    if isinstance(k, str): return ('str', k)
    return ('obj', id(k))

class LuaTable:
    _nextid = 0
    def __init__(self):
        LuaTable._nextid += 1
        self._id = LuaTable._nextid
        self.map = OrderedDict()  # kid -> (original_key, value)
        self.metatable = None
    def rawget(self, k):
        try: kid = key_id(k)
        except LuaError: return nil
        return self.map.get(kid, (None, nil))[1]
    def rawset(self, k, v):
        kid = key_id(k)
        if v is nil:
            self.map.pop(kid, None)
        else:
            self.map[kid] = (k, v)
    def array_len(self):
        n = 0
        while self.rawget(n+1) is not nil:
            n += 1
        return n
    def keys(self):
        return [kv[0] for kv in self.map.values() if kv[1] is not nil]
    def items(self):
        return [(k,v) for (k,v) in self.map.values() if v is not nil]
    def __repr__(self): return 'table: 0x%x' % (0x700000000000 + self._id*0x38)

class LuaFunction:
    _nextid = 0
    def __init__(self, params, vararg, body, closure, source='(string)', line=1, name=None):
        LuaFunction._nextid += 1
        self._id = LuaFunction._nextid
        self.params=params; self.vararg=vararg; self.body=body; self.closure=closure
        self.source=source; self.line=line; self.name=name
        self.env_table = None
    def __repr__(self): return 'function: 0x%x' % (0x710000000000 + self._id*0x30)

class BuiltinFunction:
    _nextid = 0
    def __init__(self, name, func):
        BuiltinFunction._nextid += 1
        self._id = BuiltinFunction._nextid
        self.name=name; self.func=func
    def __repr__(self): return 'function: 0x%x' % (0x720000000000 + self._id*0x20)

class LuaThread:
    _nextid = 0
    def __init__(self, func=None):
        LuaThread._nextid += 1
        self._id=LuaThread._nextid; self.func=func; self.status='suspended'; self.result=[]
    def __repr__(self): return 'thread: 0x%x' % (0x730000000000 + self._id*0x28)

class LuaFile:
    _nextid=0
    def __init__(self, f, closeable=True, name=None):
        LuaFile._nextid += 1
        self._id=LuaFile._nextid; self.f=f; self.closeable=closeable; self.closed=False; self.name=name
    def __repr__(self): return 'file (0x%x)' % (0x740000000000 + self._id*0x28)

class CData:
    _nextid=0
    def __init__(self, ctype='int', value=None, length=None):
        CData._nextid += 1
        self._id=CData._nextid; self.ctype=ctype; self.value=value; self.length=length
        if length is not None and value is None: self.value=[0]*length
    def __repr__(self): return 'cdata<%s>: 0x%x' % (self.ctype, 0x750000000000 + self._id*0x20)

class CLib:
    def __init__(self, name='C'): self.name=name

# --- Lexer ----------------------------------------------------------------

@dataclass
class Token:
    typ: str
    val: object
    line: int
    col: int

KEYWORDS=set('and break do else elseif end false for function if in local nil not or repeat return then true until while'.split())
SYMBOLS3={'...'}
SYMBOLS2={'==','~=','<=','>=','..','::'}

class Lexer:
    def __init__(self, text):
        self.text=text
        if text.startswith('#'):
            p=text.find('\n')
            if p>=0: self.text='\n'+text[p+1:]
            else: self.text='\n'
        self.n=len(self.text); self.i=0; self.line=1; self.col=1
    def peek(self, n=0):
        j=self.i+n
        return self.text[j] if j<self.n else ''
    def advance(self, count=1):
        s=''
        for _ in range(count):
            if self.i>=self.n: break
            c=self.text[self.i]; self.i+=1; s+=c
            if c=='\n': self.line+=1; self.col=1
            else: self.col+=1
        return s
    def startswith(self, s): return self.text.startswith(s, self.i)
    def skip_ws_comments(self):
        while True:
            while self.peek() and self.peek() in ' \t\r\n\v\f': self.advance()
            if self.startswith('--'):
                self.advance(2)
                if self.peek()=='[' and self.long_bracket_level(self.i) is not None:
                    self.read_long_bracket(discard=True)
                else:
                    while self.peek() and self.peek()!='\n': self.advance()
                continue
            break
    def long_bracket_level(self, pos):
        if pos>=self.n or self.text[pos]!='[': return None
        j=pos+1; eq=0
        while j<self.n and self.text[j]=='=': eq+=1; j+=1
        if j<self.n and self.text[j]=='[': return eq
        return None
    def read_long_bracket(self, discard=False):
        line0=self.line
        level=self.long_bracket_level(self.i)
        if level is None: raise LuaSyntax("invalid long string delimiter", self.line)
        self.advance(1+level+1)
        if self.peek()=='\n': self.advance()
        end=']' + '='*level + ']'
        out=[]
        while not self.startswith(end):
            if not self.peek(): raise LuaSyntax("unfinished long string near '<eof>'", line0)
            out.append(self.advance())
        self.advance(len(end))
        return '' if discard else ''.join(out)
    def next(self):
        self.skip_ws_comments()
        line,col=self.line,self.col
        c=self.peek()
        if not c: return Token('EOF','<eof>',line,col)
        if self.startswith('...'):
            self.advance(3); return Token('...', '...', line,col)
        two=self.text[self.i:self.i+2]
        if two in SYMBOLS2:
            self.advance(2); return Token(two,two,line,col)
        if c in '+-*/%^#=<>;:,.(){}[]':
            if c=='[' and self.long_bracket_level(self.i) is not None:
                s=self.read_long_bracket(False); return Token('STRING',s,line,col)
            self.advance(); return Token(c,c,line,col)
        if c in ('"',"'"):
            return self.read_string()
        if c.isdigit() or (c=='.' and self.peek(1).isdigit()):
            return self.read_number()
        if c.isalpha() or c=='_':
            ident=''
            while self.peek() and (self.peek().isalnum() or self.peek()=='_'):
                ident+=self.advance()
            if ident in KEYWORDS: return Token(ident,ident,line,col)
            return Token('NAME',ident,line,col)
        self.advance()
        return Token(c,c,line,col)
    def read_string(self):
        quote=self.peek(); line,col=self.line,self.col; self.advance()
        out=[]
        while True:
            c=self.peek()
            if not c or c=='\n': raise LuaSyntax("unfinished string near '<eof>'" if not c else "unfinished string near '"+quote+"'", line)
            if c==quote: self.advance(); break
            if c!='\\': out.append(self.advance()); continue
            self.advance(); e=self.peek()
            if not e: raise LuaSyntax("unfinished string near '<eof>'", line)
            mapping={'a':'\a','b':'\b','f':'\f','n':'\n','r':'\r','t':'\t','v':'\v','\\':'\\','"':'"',"'":"'"}
            if e in mapping:
                out.append(mapping[e]); self.advance()
            elif e=='\n': self.advance()
            elif e=='z':
                self.advance()
                while self.peek() and self.peek() in ' \t\r\n\v\f': self.advance()
            elif e=='x':
                self.advance(); hx=self.advance()+self.advance()
                try: out.append(chr(int(hx,16)))
                except Exception: out.append('')
            elif e.isdigit():
                digs=''
                for _ in range(3):
                    if self.peek().isdigit(): digs+=self.advance()
                    else: break
                out.append(chr(int(digs[:3])%256))
            else:
                out.append(self.advance())
        return Token('STRING',''.join(out),line,col)
    def read_number(self):
        line,col=self.line,self.col
        s=''
        if self.startswith('0x') or self.startswith('0X'):
            s+=self.advance(2)
            while self.peek() and (self.peek().isdigit() or self.peek().lower() in 'abcdef' or self.peek() in '.pP+-'):
                # stop signs except after p/P
                if self.peek() in '+-' and not (s and s[-1] in 'pP'): break
                s+=self.advance()
        else:
            while self.peek() and (self.peek().isdigit() or self.peek() in '.eE+-'):
                if self.peek() in '+-' and not (s and s[-1] in 'eE'): break
                if self.peek()=='.' and self.peek(1)=='.': break
                s+=self.advance()
        n=parse_lua_number(s, silent=True)
        if n is None: n=0
        return Token('NUMBER',n,line,col)

# --- Parser AST -----------------------------------------------------------

@dataclass
class Chunk: body: list
@dataclass
class Var: name: str; line:int=1
@dataclass
class Lit: value: object; line:int=1
@dataclass
class Vararg: line:int=1
@dataclass
class Unary: op:str; expr:object; line:int=1
@dataclass
class Binary: op:str; left:object; right:object; line:int=1
@dataclass
class Index: obj:object; key:object; line:int=1
@dataclass
class Call: func:object; args:list; selfarg:object=None; line:int=1
@dataclass
class FuncExpr: params:list; vararg:bool; body:list; line:int=1
@dataclass
class TableExpr: fields:list; line:int=1

@dataclass
class Assign: targets:list; exprs:list; line:int=1
@dataclass
class LocalAssign: names:list; exprs:list; line:int=1
@dataclass
class LocalFunc: name:str; func:FuncExpr; line:int=1
@dataclass
class FuncDef: target:object; func:FuncExpr; line:int=1
@dataclass
class IfStmt: branches:list; elsebody:list; line:int=1
@dataclass
class WhileStmt: cond:object; body:list; line:int=1
@dataclass
class RepeatStmt: body:list; cond:object; line:int=1
@dataclass
class ForNum: var:str; start:object; end:object; step:object; body:list; line:int=1
@dataclass
class ForIn: names:list; exprs:list; body:list; line:int=1
@dataclass
class DoStmt: body:list; line:int=1
@dataclass
class ReturnStmt: exprs:list; line:int=1
@dataclass
class BreakStmt: line:int=1
@dataclass
class CallStmt: call:Call; line:int=1

class Parser:
    def __init__(self, text):
        self.lex=Lexer(text); self.tok=self.lex.next()
    def error(self, msg=None):
        if msg is None: msg="unexpected symbol near '%s'" % self.tok.val
        raise LuaSyntax(msg, self.tok.line)
    def consume(self, typ=None):
        t=self.tok
        if typ and t.typ!=typ: self.error("'%s' expected near '%s'" % (typ, t.val))
        self.tok=self.lex.next(); return t
    def match(self, typ):
        if self.tok.typ==typ: return self.consume()
        return None
    def parse(self):
        return self.parse_block({'EOF'})
    def parse_block(self, stops):
        body=[]
        while self.tok.typ not in stops:
            if self.tok.typ=='EOF':
                if 'EOF' in stops: break
                self.error("'end' expected near '<eof>'")
            if self.match(';'): continue
            body.append(self.parse_stmt())
            self.match(';')
        return body
    def parse_stmt(self):
        t=self.tok; typ=t.typ
        if typ=='if': return self.parse_if()
        if typ=='while': return self.parse_while()
        if typ=='repeat': return self.parse_repeat()
        if typ=='for': return self.parse_for()
        if typ=='do':
            line=self.consume().line; body=self.parse_block({'end'}); self.consume('end'); return DoStmt(body,line)
        if typ=='function': return self.parse_funcdef()
        if typ=='local': return self.parse_local()
        if typ=='return':
            line=self.consume().line
            exprs=[]
            if self.tok.typ not in {'EOF','end','else','elseif','until',';'}:
                exprs=self.parse_explist()
            return ReturnStmt(exprs,line)
        if typ=='break': return BreakStmt(self.consume().line)
        # assignment or call
        line=self.tok.line
        first=self.parse_prefixexp()
        if isinstance(first, Call): return CallStmt(first,line)
        targets=[first]
        while self.match(','):
            targets.append(self.parse_prefixexp())
        self.consume('=')
        exprs=self.parse_explist()
        return Assign(targets,exprs,line)
    def parse_if(self):
        line=self.consume('if').line
        cond=self.parse_expr(); self.consume('then')
        body=self.parse_block({'elseif','else','end'})
        branches=[(cond,body)]
        while self.tok.typ=='elseif':
            self.consume(); c=self.parse_expr(); self.consume('then')
            b=self.parse_block({'elseif','else','end'}); branches.append((c,b))
        elsebody=[]
        if self.tok.typ=='else':
            self.consume(); elsebody=self.parse_block({'end'})
        self.consume('end'); return IfStmt(branches,elsebody,line)
    def parse_while(self):
        line=self.consume('while').line; cond=self.parse_expr(); self.consume('do')
        body=self.parse_block({'end'}); self.consume('end'); return WhileStmt(cond,body,line)
    def parse_repeat(self):
        line=self.consume('repeat').line; body=self.parse_block({'until'}); self.consume('until'); cond=self.parse_expr(); return RepeatStmt(body,cond,line)
    def parse_for(self):
        line=self.consume('for').line; name=self.consume('NAME').val
        if self.match('='):
            start=self.parse_expr(); self.consume(','); end=self.parse_expr(); step=Lit(1,line)
            if self.match(','): step=self.parse_expr()
            self.consume('do'); body=self.parse_block({'end'}); self.consume('end')
            return ForNum(name,start,end,step,body,line)
        names=[name]
        while self.match(','): names.append(self.consume('NAME').val)
        self.consume('in'); exprs=self.parse_explist(); self.consume('do'); body=self.parse_block({'end'}); self.consume('end')
        return ForIn(names,exprs,body,line)
    def parse_funcdef(self):
        line=self.consume('function').line
        target, method = self.parse_funcname()
        func=self.parse_funcbody(line, method)
        return FuncDef(target,func,line)
    def parse_funcname(self):
        line=self.tok.line
        target=Var(self.consume('NAME').val,line)
        while self.match('.'):
            key=Lit(self.consume('NAME').val,self.tok.line)
            target=Index(target,key,line)
        method=False
        if self.match(':'):
            key=Lit(self.consume('NAME').val,self.tok.line)
            target=Index(target,key,line); method=True
        return target,method
    def parse_local(self):
        line=self.consume('local').line
        if self.tok.typ=='function':
            self.consume(); name=self.consume('NAME').val; func=self.parse_funcbody(line, False); return LocalFunc(name,func,line)
        names=[self.consume('NAME').val]
        while self.match(','): names.append(self.consume('NAME').val)
        exprs=[]
        if self.match('='): exprs=self.parse_explist()
        return LocalAssign(names,exprs,line)
    def parse_funcbody(self, line=None, method=False):
        if line is None: line=self.tok.line
        self.consume('(')
        params=[]; vararg=False
        if self.tok.typ!=')':
            while True:
                if self.tok.typ=='...': self.consume(); vararg=True; break
                params.append(self.consume('NAME').val)
                if not self.match(','): break
            if method: params.insert(0,'self')
        elif method:
            params.insert(0,'self')
        self.consume(')')
        body=self.parse_block({'end'}); self.consume('end')
        return FuncExpr(params,vararg,body,line)
    def parse_explist(self):
        xs=[self.parse_expr()]
        while self.match(','): xs.append(self.parse_expr())
        return xs
    PRECEDENCE={'or':1,'and':2,'<':3,'>':3,'<=':3,'>=':3,'~=':3,'==':3,'..':4,'+':5,'-':5,'*':6,'/':6,'%':6,'^':8}
    RIGHT={'^','..'}
    def parse_expr(self, minp=0):
        t=self.tok
        if t.typ in {'not','#','-'}:
            self.consume(); left=Unary(t.typ,self.parse_expr(7),t.line)
        else:
            left=self.parse_simple()
        while self.tok.typ in self.PRECEDENCE and self.PRECEDENCE[self.tok.typ] >= minp:
            op=self.tok.typ; prec=self.PRECEDENCE[op]; line=self.tok.line; self.consume()
            rhs=self.parse_expr(prec if op in self.RIGHT else prec+1)
            left=Binary(op,left,rhs,line)
        return left
    def parse_simple(self):
        t=self.tok
        if t.typ=='nil': self.consume(); return Lit(nil,t.line)
        if t.typ=='true': self.consume(); return Lit(True,t.line)
        if t.typ=='false': self.consume(); return Lit(False,t.line)
        if t.typ=='NUMBER': self.consume(); return Lit(t.val,t.line)
        if t.typ=='STRING': self.consume(); return Lit(t.val,t.line)
        if t.typ=='...': self.consume(); return Vararg(t.line)
        if t.typ=='function': self.consume(); return self.parse_funcbody(t.line, False)
        if t.typ=='{': return self.parse_table()
        return self.parse_prefixexp()
    def parse_prefixexp(self):
        t=self.tok
        if t.typ=='NAME': expr=Var(self.consume().val,t.line)
        elif t.typ=='(':
            self.consume(); expr=self.parse_expr(); self.consume(')')
        else:
            self.error()
        while True:
            if self.match('.'):
                name=self.consume('NAME'); expr=Index(expr,Lit(name.val,name.line),name.line)
            elif self.match('['):
                key=self.parse_expr(); self.consume(']'); expr=Index(expr,key,t.line)
            elif self.tok.typ in {'(', '{', 'STRING'}:
                args=self.parse_args(); expr=Call(expr,args,None,t.line)
            elif self.match(':'):
                name=self.consume('NAME'); args=self.parse_args();
                obj=expr; expr=Call(Index(obj,Lit(name.val,name.line),name.line),args,obj,name.line)
            else: break
        return expr
    def parse_args(self):
        if self.match('('):
            args=[]
            if self.tok.typ!=')': args=self.parse_explist()
            self.consume(')'); return args
        if self.tok.typ=='{': return [self.parse_table()]
        if self.tok.typ=='STRING': t=self.consume(); return [Lit(t.val,t.line)]
        self.error("function arguments expected near '%s'" % self.tok.val)
    def parse_table(self):
        line=self.consume('{').line; fields=[]; array_count=0
        while self.tok.typ!='}':
            if self.tok.typ=='[':
                self.consume(); key=self.parse_expr(); self.consume(']'); self.consume('='); val=self.parse_expr(); fields.append(('rec',key,val))
            elif self.tok.typ=='NAME':
                # name=expr or array expression
                save_tok=self.tok; save_lex=(self.lex.i,self.lex.line,self.lex.col)
                name=self.consume('NAME')
                if self.match('='):
                    val=self.parse_expr(); fields.append(('rec',Lit(name.val,name.line),val))
                else:
                    # restore by reconstructing a Var expression as start, then parse binary suffix manually impossible.
                    # Instead parse as Var plus binary/postfix already lost. Put token back by reparsing is awkward;
                    # use a small token pushback via stored state.
                    self.lex.i,self.lex.line,self.lex.col=save_lex; self.tok=save_tok
                    val=self.parse_expr(); fields.append(('arr',val))
            else:
                val=self.parse_expr(); fields.append(('arr',val))
            if not (self.match(',') or self.match(';')): break
            if self.tok.typ=='}': break
        self.consume('}'); return TableExpr(fields,line)

# --- Environment ----------------------------------------------------------

class Env:
    def __init__(self, interp, parent=None):
        self.interp=interp; self.parent=parent; self.locals={}; self.varargs=[]
    def child(self): return Env(self.interp,self)
    def define(self, name, val=nil): self.locals[name]=val
    def find_env(self, name):
        if name in self.locals: return self
        if self.parent: return self.parent.find_env(name)
        return None
    def get(self, name):
        e=self.find_env(name)
        if e: return e.locals.get(name,nil)
        return self.interp.table_get(self.interp.globals, name)
    def set(self, name, val):
        e=self.find_env(name)
        if e: e.locals[name]=val
        else: self.interp.table_set(self.interp.globals, name, val)

# --- Interpreter ----------------------------------------------------------

class Interpreter:
    def __init__(self, prog='./executable', ignore_env=False):
        self.prog=prog; self.ignore_env=ignore_env; self.globals=LuaTable(); self.base_env=Env(self)
        self.callstack=[]; self.current_source='(command line)'; self.current_line=1
        self.jit_on=True; self.last_error=None
        self.registry=LuaTable(); self.stdin_file=LuaFile(sys.stdin,False,'stdin'); self.stdout_file=LuaFile(sys.stdout,False,'stdout'); self.stderr_file=LuaFile(sys.stderr,False,'stderr')
        self.current_input=self.stdin_file; self.current_output=self.stdout_file
        self.init_builtins()
    # table/metamethod helpers
    def get_metamethod(self, v, name):
        mt = v.metatable if isinstance(v,LuaTable) else None
        if isinstance(v, (str,int,float,bool)):
            mt = self.primitive_mts.get(lua_type(v)) if hasattr(self,'primitive_mts') else None
        if mt: return mt.rawget(name)
        return nil
    def table_get(self, obj, key):
        if isinstance(obj,LuaTable):
            v=obj.rawget(key)
            if v is not nil: return v
            mm = obj.metatable.rawget('__index') if obj.metatable else nil
            if mm is not nil:
                if isinstance(mm,LuaTable): return self.table_get(mm,key)
                return first(self.call(mm,[obj,key]))
            return nil
        if isinstance(obj,str):
            # string methods through string table
            st=self.globals.rawget('string')
            if isinstance(st,LuaTable):
                v=st.rawget(key)
                if v is not nil: return v
        if isinstance(obj,LuaFile):
            ft=getattr(self,'file_methods',None)
            if isinstance(ft,LuaTable):
                v=ft.rawget(key)
                if v is not nil: return v
        if isinstance(obj,CData):
            if is_num(key):
                idx=int(key)
                if isinstance(obj.value,list) and 0 <= idx < len(obj.value): return obj.value[idx]
                return nil
            if isinstance(obj.value,LuaTable): return self.table_get(obj.value,key)
        if isinstance(obj,CLib):
            return BuiltinFunction(str(key), lambda interp,args, _name=str(key): [0])
        raise LuaError("attempt to index a %s value" % lua_type(obj), self.current_line, self.current_source)
    def table_set(self, obj, key, val):
        if isinstance(obj,LuaTable):
            old=obj.rawget(key)
            if old is nil and obj.metatable:
                mm=obj.metatable.rawget('__newindex')
                if mm is not nil:
                    if isinstance(mm,LuaTable): self.table_set(mm,key,val); return
                    self.call(mm,[obj,key,val]); return
            obj.rawset(key,val); return
        if isinstance(obj,CData) and is_num(key):
            idx=int(key)
            if isinstance(obj.value,list) and 0 <= idx < len(obj.value): obj.value[idx]=val; return
        raise LuaError("attempt to index a %s value" % lua_type(obj), self.current_line, self.current_source)
    def length(self, v):
        if isinstance(v,str): return len(v)
        if isinstance(v,LuaTable):
            mm=self.get_metamethod(v,'__len')
            if mm is not nil: return first(self.call(mm,[v]))
            return v.array_len()
        raise LuaError("attempt to get length of a %s value" % lua_type(v), self.current_line, self.current_source)
    def tostring(self, v):
        if v is nil: return 'nil'
        if isinstance(v,bool): return 'true' if v else 'false'
        if is_num(v): return format_number(v)
        if isinstance(v,str): return v
        mm=self.get_metamethod(v,'__tostring')
        if mm is not nil:
            r=first(self.call(mm,[v])); return self.tostring(r)
        return repr(v)
    def call(self, func, args, name=None):
        if isinstance(func,BuiltinFunction):
            self.callstack.append(('[C]', func.name, self.current_line))
            try:
                r=func.func(self,args)
                if r is None: return []
                return r if isinstance(r,list) else [r]
            except LuaError:
                raise
            finally:
                if self.callstack: self.callstack.pop()
        if isinstance(func,LuaFunction):
            self.callstack.append((func.source, func.name or name or '?', func.line))
            fenv=Env(self, func.closure)
            for i,p in enumerate(func.params): fenv.define(p, args[i] if i<len(args) else nil)
            fenv.varargs=args[len(func.params):] if func.vararg else []
            oldsrc,oldline=self.current_source,self.current_line
            self.current_source=func.source
            try:
                self.exec_block(func.body, fenv)
                return []
            except LuaReturn as r:
                return r.vals
            finally:
                self.current_source,self.current_line=oldsrc,oldline
                if self.callstack: self.callstack.pop()
        mm=self.get_metamethod(func,'__call')
        if mm is not nil: return self.call(mm,[func]+args)
        raise LuaError("attempt to call a %s value" % lua_type(func), self.current_line, self.current_source)
    # eval
    def eval(self, expr, env):
        vals=self.eval_multi(expr,env)
        return vals[0] if vals else nil
    def eval_multi(self, expr, env):
        self.current_line=getattr(expr,'line',self.current_line)
        if isinstance(expr,Lit): return [expr.value]
        if isinstance(expr,Var): return [env.get(expr.name)]
        if isinstance(expr,Vararg): return list(env.varargs)
        if isinstance(expr,Unary):
            v=self.eval(expr.expr,env)
            if expr.op=='not': return [not truthy(v)]
            if expr.op=='#': return [self.length(v)]
            if expr.op=='-':
                n=number_value(v); return [normalize_number(-n)]
        if isinstance(expr,Binary): return [self.eval_binary(expr,env)]
        if isinstance(expr,Index): return [self.table_get(self.eval(expr.obj,env), self.eval(expr.key,env))]
        if isinstance(expr,Call):
            args=[]
            if expr.selfarg is not None: args.append(self.eval(expr.selfarg,env))
            args += self.eval_exprlist(expr.args,env)
            func=self.eval(expr.func,env)
            return self.call(func,args)
        if isinstance(expr,FuncExpr): return [LuaFunction(expr.params,expr.vararg,expr.body,env,self.current_source,expr.line)]
        if isinstance(expr,TableExpr): return [self.eval_table(expr,env)]
        raise LuaError('internal error: bad expression')
    def eval_binary(self, expr, env):
        op=expr.op
        if op=='and':
            l=self.eval(expr.left,env); return self.eval(expr.right,env) if truthy(l) else l
        if op=='or':
            l=self.eval(expr.left,env); return l if truthy(l) else self.eval(expr.right,env)
        l=self.eval(expr.left,env); r=self.eval(expr.right,env)
        if op in ['+','-','*','/','%','^']:
            a=number_value(l); b=number_value(r)
            if op=='+': return normalize_number(a+b)
            if op=='-': return normalize_number(a-b)
            if op=='*': return normalize_number(a*b)
            if op=='/': return a/b
            if op=='%': return normalize_number(a - _math.floor(a/b)*b)
            if op=='^': return normalize_number(a**b)
        if op=='..': return self.tostring(l)+self.tostring(r)
        if op in ['==','~=']:
            eq=lua_equal(l,r); return eq if op=='==' else not eq
        if op in ['<','>','<=','>=']:
            if is_num(l) and is_num(r): pass
            elif isinstance(l,str) and isinstance(r,str): pass
            else: raise LuaError("attempt to compare %s with %s"%(lua_type(l),lua_type(r)),expr.line,self.current_source)
            if op=='<': return l<r
            if op=='>': return l>r
            if op=='<=': return l<=r
            if op=='>=': return l>=r
        raise LuaError('unknown operator '+op)
    def eval_exprlist(self, exprs, env, wanted=None):
        vals=[]
        for i,e in enumerate(exprs):
            if i==len(exprs)-1: vals.extend(self.eval_multi(e,env))
            else: vals.append(self.eval(e,env))
        if wanted is not None:
            vals=vals[:wanted]+[nil]*max(0,wanted-len(vals))
        return vals
    def eval_table(self, expr, env):
        t=LuaTable(); arr=1
        for idx,field in enumerate(expr.fields):
            if field[0]=='rec':
                k=self.eval(field[1],env); v=self.eval(field[2],env); t.rawset(k,v)
            else:
                e=field[1]
                vals=self.eval_multi(e,env) if idx==len(expr.fields)-1 else [self.eval(e,env)]
                for v in vals:
                    if v is not nil: t.rawset(arr,v)
                    arr+=1
        return t
    def assign_target(self, target, val, env):
        if isinstance(target,Var): env.set(target.name,val); return
        if isinstance(target,Index): self.table_set(self.eval(target.obj,env), self.eval(target.key,env), val); return
        raise LuaError('syntax error: bad assignment target')
    def exec_block(self, body, env):
        for st in body: self.exec_stmt(st,env)
    def exec_stmt(self, st, env):
        self.current_line=getattr(st,'line',self.current_line)
        if isinstance(st,Assign):
            vals=self.eval_exprlist(st.exprs,env,wanted=len(st.targets))
            for t,v in zip(st.targets,vals): self.assign_target(t,v,env)
        elif isinstance(st,LocalAssign):
            vals=self.eval_exprlist(st.exprs,env,wanted=len(st.names)) if st.exprs else [nil]*len(st.names)
            for n,v in zip(st.names,vals): env.define(n,v)
        elif isinstance(st,LocalFunc):
            env.define(st.name,nil); f=LuaFunction(st.func.params,st.func.vararg,st.func.body,env,self.current_source,st.func.line,st.name); env.set(st.name,f)
        elif isinstance(st,FuncDef):
            f=LuaFunction(st.func.params,st.func.vararg,st.func.body,env,self.current_source,st.func.line, target_name(st.target))
            self.assign_target(st.target,f,env)
        elif isinstance(st,IfStmt):
            for cond,body in st.branches:
                if truthy(self.eval(cond,env)):
                    self.exec_block(body,env.child()); return
            if st.elsebody: self.exec_block(st.elsebody,env.child())
        elif isinstance(st,WhileStmt):
            while truthy(self.eval(st.cond,env)):
                try: self.exec_block(st.body,env.child())
                except LuaBreak: break
        elif isinstance(st,RepeatStmt):
            renv=env.child()
            while True:
                try: self.exec_block(st.body,renv)
                except LuaBreak: break
                if truthy(self.eval(st.cond,renv)): break
        elif isinstance(st,ForNum):
            start=number_value(self.eval(st.start,env)); end=number_value(self.eval(st.end,env)); step=number_value(self.eval(st.step,env))
            i=start
            def cont(i): return i<=end if step>=0 else i>=end
            while cont(i):
                lenv=env.child(); lenv.define(st.var, normalize_number(i))
                try: self.exec_block(st.body,lenv)
                except LuaBreak: break
                i += step
        elif isinstance(st,ForIn):
            vals=self.eval_exprlist(st.exprs,env,wanted=3)
            gen,state,ctrl=vals[0],vals[1],vals[2]
            while True:
                res=self.call(gen,[state,ctrl])
                firstv=res[0] if res else nil
                if firstv is nil: break
                ctrl=firstv; lenv=env.child()
                for i,n in enumerate(st.names): lenv.define(n,res[i] if i<len(res) else nil)
                try: self.exec_block(st.body,lenv)
                except LuaBreak: break
        elif isinstance(st,DoStmt): self.exec_block(st.body,env.child())
        elif isinstance(st,ReturnStmt): raise LuaReturn(self.eval_exprlist(st.exprs,env) if st.exprs else [])
        elif isinstance(st,BreakStmt): raise LuaBreak()
        elif isinstance(st,CallStmt): self.eval_multi(st.call,env)
        else: raise LuaError('internal error: bad statement')
    def run_chunk(self, code, source='(command line)', env=None):
        oldsrc=self.current_source; self.current_source=source
        try:
            body=Parser(code).parse()
        except LuaSyntax as e:
            self.current_source=oldsrc
            raise LuaError("%s:%d: %s" % (source,e.line,e.msg), e.line, source, add_location=False)
        env=env or self.base_env
        self.callstack.append((source,'main chunk',1))
        try:
            self.exec_block(body, env)
            return []
        except LuaReturn as r:
            return r.vals
        finally:
            if self.callstack: self.callstack.pop()
            self.current_source=oldsrc
    # builtins -------------------------------------------------------------
    def init_builtins(self):
        g=self.globals; self.primitive_mts={}
        def setg(n,v): g.rawset(n,v)
        setg('_G', g); setg('_VERSION', LUA_VERSION)
        # base
        for n,f in {
            'assert':b_assert,'collectgarbage':b_collectgarbage,'dofile':b_dofile,'error':b_error,
            'getfenv':b_getfenv,'getmetatable':b_getmetatable,'ipairs':b_ipairs,'load':b_load,
            'loadfile':b_loadfile,'loadstring':b_loadstring,'module':b_module,'newproxy':b_newproxy,
            'next':b_next,'pairs':b_pairs,'pcall':b_pcall,'print':b_print,'rawequal':b_rawequal,
            'rawget':b_rawget,'rawset':b_rawset,'require':b_require,'select':b_select,
            'setfenv':b_setfenv,'setmetatable':b_setmetatable,'tonumber':b_tonumber,
            'tostring':b_tostring,'type':b_type,'unpack':b_unpack,'xpcall':b_xpcall,
            'gcinfo':b_gcinfo}.items(): setg(n,BuiltinFunction(n,f))
        # libraries
        self.string_table=make_string_lib(self); setg('string',self.string_table)
        self.table_table=make_table_lib(self); setg('table',self.table_table)
        self.math_table=make_math_lib(self); setg('math',self.math_table)
        self.os_table=make_os_lib(self); setg('os',self.os_table)
        self.coroutine_table=make_coroutine_lib(self); setg('coroutine',self.coroutine_table)
        self.debug_table=make_debug_lib(self); setg('debug',self.debug_table)
        self.bit_table=make_bit_lib(self); setg('bit',self.bit_table)
        self.jit_table=make_jit_lib(self); setg('jit',self.jit_table)
        self.file_methods=make_file_methods(self)
        self.io_table=make_io_lib(self); setg('io',self.io_table)
        self.package_table=make_package_lib(self); setg('package',self.package_table)
        # package.loaded setup
        loaded=self.package_table.rawget('loaded')
        for n in ['_G','coroutine','table','io','os','string','math','debug','package','bit','jit']:
            loaded.rawset(n, g.rawget(n))
        loaded.rawset('jit.opt', self.jit_table.rawget('opt'))
    def format_error(self, e):
        if not isinstance(e,LuaError): e=LuaError(str(e), self.current_line, self.current_source)
        if e.add_location and e.source:
            first="%s:%s:%d: %s"%(self.prog,e.source,e.line or 1,e.msg)
        else:
            first="%s: %s"%(self.prog,e.msg)
        # If message already starts with source:line, don't add extra.
        out=[first]
        if e.add_location:
            out.append('stack traceback:')
            # Simplified stack, top-level enough for common tests.
            for src,name,line in reversed(self.callstack):
                if src=='[C]': out.append("\t[C]: in function '%s'"%name)
                elif name=='main chunk': out.append("\t%s:%d: in main chunk"%(src,line or 1))
                else: out.append("\t%s:%d: in function '%s'"%(src,line or 1,name))
            out.append('\t[C]: at 0x5555555553a0')
        return '\n'.join(out)

def first(vals): return vals[0] if vals else nil

def lua_equal(a,b):
    if a is nil and b is nil: return True
    if is_num(a) and is_num(b): return float(a)==float(b)
    if isinstance(a,bool) or isinstance(b,bool): return isinstance(a,bool) and isinstance(b,bool) and a==b
    if isinstance(a,str) or isinstance(b,str): return isinstance(a,str) and isinstance(b,str) and a==b
    return a is b

def target_name(t):
    if isinstance(t,Var): return t.name
    if isinstance(t,Index) and isinstance(t.key,Lit) and isinstance(t.key.value,str): return t.key.value
    return '?'

def parse_lua_number(s, silent=False):
    try:
        st=s.strip()
        if not st: raise ValueError
        if st.lower().startswith('0x'):
            if any(c in st for c in '.pP'):
                return normalize_number(float.fromhex(st))
            return int(st,16)
        if re.match(r'^[+-]?\d+$',st): return int(st,10)
        return normalize_number(float(st))
    except Exception:
        if silent: return None
        raise

# --- base builtin functions ----------------------------------------------

def arg(args,i,default=nil): return args[i] if i<len(args) else default

def b_print(I,args):
    sys.stdout.write('\t'.join(I.tostring(a) for a in args)+'\n'); sys.stdout.flush(); return []
def b_tostring(I,args): return [I.tostring(arg(args,0))]
def b_type(I,args): return [lua_type(arg(args,0))]
def b_assert(I,args):
    if truthy(arg(args,0)): return args
    msg=arg(args,1,'assertion failed!')
    raise LuaError(I.tostring(msg), I.current_line, I.current_source)
def b_error(I,args):
    msg=arg(args,0,nil)
    raise LuaError(I.tostring(msg), I.current_line, I.current_source)
def b_pcall(I,args):
    f=arg(args,0)
    try: return [True]+I.call(f,args[1:])
    except LuaError as e: return [False,e.msg]
def b_xpcall(I,args):
    f=arg(args,0); handler=arg(args,1)
    try: return [True]+I.call(f,[])
    except LuaError as e:
        try: h=first(I.call(handler,[e.msg])) if handler is not nil else e.msg
        except LuaError: h=e.msg
        return [False,h]
def b_tonumber(I,args):
    v=arg(args,0); base=arg(args,1,nil)
    if base is nil:
        if is_num(v): return [v]
        if isinstance(v,str):
            n=parse_lua_number(v, silent=True); return [n if n is not None else nil]
        return [nil]
    try:
        b=int(number_value(base)); s=str(v).strip();
        if not (2<=b<=36): raise ValueError
        return [int(s,b)]
    except Exception: return [nil]
def b_select(I,args):
    idx=arg(args,0)
    rest=args[1:]
    if idx=='#': return [len(rest)]
    n=int(number_value(idx));
    if n<0: n=len(rest)+n+1
    if n<1: raise LuaError("bad argument #1 to 'select' (index out of range)", I.current_line,I.current_source)
    return rest[n-1:]
def b_unpack(I,args):
    t=arg(args,0); i=int(number_value(arg(args,1,1))); jarg=arg(args,2,nil); j=int(number_value(jarg)) if jarg is not nil else (t.array_len() if isinstance(t,LuaTable) else 0)
    return [I.table_get(t,k) for k in range(i,j+1)]
def b_next(I,args):
    t=arg(args,0); k=arg(args,1,nil)
    if not isinstance(t,LuaTable): raise LuaError("bad argument #1 to 'next' (table expected, got %s)"%lua_type(t),I.current_line,I.current_source)
    items=t.items()
    if k is nil:
        return list(items[0]) if items else [nil]
    kid=key_id(k); seen=False
    for kk,v in items:
        if seen: return [kk,v]
        if key_id(kk)==kid: seen=True
    return [nil]
def b_pairs(I,args): return [I.globals.rawget('next'), arg(args,0), nil]
def _ipairs_iter(I,args):
    t=arg(args,0); i=int(number_value(arg(args,1,0)))+1; v=I.table_get(t,i)
    if v is nil: return [nil]
    return [i,v]
def b_ipairs(I,args): return [BuiltinFunction('ipairs iterator',_ipairs_iter), arg(args,0), 0]
def b_rawequal(I,args): return [lua_equal(arg(args,0),arg(args,1))]
def b_rawget(I,args):
    t=arg(args,0); return [t.rawget(arg(args,1)) if isinstance(t,LuaTable) else nil]
def b_rawset(I,args):
    t=arg(args,0)
    if not isinstance(t,LuaTable): raise LuaError("bad argument #1 to 'rawset' (table expected, got %s)"%lua_type(t),I.current_line,I.current_source)
    t.rawset(arg(args,1),arg(args,2)); return [t]
def b_getmetatable(I,args):
    v=arg(args,0); mt=v.metatable if isinstance(v,LuaTable) else None
    if mt and mt.rawget('__metatable') is not nil: return [mt.rawget('__metatable')]
    return [mt if mt else nil]
def b_setmetatable(I,args):
    t=arg(args,0); mt=arg(args,1)
    if not isinstance(t,LuaTable): raise LuaError("bad argument #1 to 'setmetatable' (table expected, got %s)"%lua_type(t),I.current_line,I.current_source)
    if t.metatable and t.metatable.rawget('__metatable') is not nil: raise LuaError('cannot change a protected metatable',I.current_line,I.current_source)
    t.metatable = mt if isinstance(mt,LuaTable) else None
    return [t]
def b_collectgarbage(I,args): return [0]
def b_gcinfo(I,args): return [0]
def b_getfenv(I,args):
    f=arg(args,0,nil)
    if f is nil or f==0: return [I.globals]
    if isinstance(f,LuaFunction) and f.env_table: return [f.env_table]
    return [I.globals]
def b_setfenv(I,args):
    f=arg(args,0); env=arg(args,1)
    if isinstance(f,LuaFunction) and isinstance(env,LuaTable): f.env_table=env
    return [f]
def b_loadstring(I,args):
    code=arg(args,0,''); name=arg(args,1,'=(loadstring)')
