def b_require(I,args):
    name=arg(args,0)
    loaded=I.package_table.rawget('loaded')
    cur=loaded.rawget(name)
    if cur is not nil: return [cur]
    # built-in ffi is loaded lazily
    if name=='ffi':
        ffi=make_ffi_lib(I); loaded.rawset('ffi',ffi); return [ffi]
    msgs=[]; loaders=I.package_table.rawget('loaders')
    i=1
    while True:
        loader=loaders.rawget(i)
        if loader is nil: break
        res=I.call(loader,[name])
        f=res[0] if res else nil
        if isinstance(f,(LuaFunction,BuiltinFunction)):
            out=I.call(f,[name, res[1] if len(res)>1 else nil])
            val=out[0] if out else nil
            if val is nil:
                if loaded.rawget(name) is nil: loaded.rawset(name,True)
            else: loaded.rawset(name,val)
            return [loaded.rawget(name)]
        elif isinstance(f,str): msgs.append(f)
        i+=1
    raise LuaError("module '%s' not found:%s"%(name,''.join(msgs)), I.current_line,I.current_source)

