def s_gsub(I,args):
    s=str(arg(args,0,'')); pat=str(arg(args,1,'')); repl=arg(args,2,''); narg=arg(args,3,nil); maxn=0 if narg is nil else int(number_value(narg))
    regex=re.compile(lua_pattern_to_re(pat),re.S); count=0
