                x=mm.group(1)
                if x=='%': return '%'
                if x=='0': return m.group(0)
                if x.isdigit():
                    try: return m.group(int(x)) or ''
                    except Exception: return ''
                return x
            return re.sub(r'%([%0-9])',rr,repl)
