        if i+1<len(fmt) and fmt[i+1]=='%': out+='%'; i+=2; continue
        j=i+1
        while j<len(fmt) and fmt[j] not in 'cdiouxXeEfgGqs': j+=1
        if j>=len(fmt): out+='%'; i+=1; continue
        spec=fmt[i:j+1]; conv=fmt[j]; v=vals[vi] if vi<len(vals) else nil; vi+=1
        try:
            if conv=='q': out+='"'+str(v).replace('\\','\\\\').replace('"','\\"').replace('\n','\\n')+'"'
            elif conv=='s': out+=spec%I.tostring(v)
            elif conv in 'cdiouxX': out+=spec%int(number_value(v))
            else: out+=spec%float(number_value(v))
        except Exception: out+=I.tostring(v)
        i=j+1
    return [out]

