    while True:
        sys.stdout.write('> '); sys.stdout.flush()
        line=sys.stdin.readline()
        if line=='': sys.stdout.write('\n'); break
        code=line
        if line.startswith('='): code='return '+line[1:]
        try:
            vals=I.run_chunk(code,'stdin')
            if vals: sys.stdout.write('\t'.join(I.tostring(v) for v in vals)+'\n')
        except LuaError as e:
            sys.stderr.write(I.format_error(e)+'\n')

def execute_main(argv):
    prog=argv[0] if argv else './executable'
    # parse enough before creating interpreter to honor -E for env.
    ignore_env='-E' in argv[1:]
    I=Interpreter(prog, ignore_env)
    # process LUA_INIT before chunks unless -E
    actions=[]; interactive=False; show_version=False; script_index=None; script_name=None; stdin_script=False
    i=1
    while i<len(argv):
        a=argv[i]
        if a=='--':
            script_index=i+1 if i+1<len(argv) else None; script_name=argv[i+1] if i+1<len(argv) else None; break
        if a=='-':
            script_index=i; script_name='-'; stdin_script=True; break
        if not a.startswith('-') or a=='':
            script_index=i; script_name=a; break
        if a=='-v': show_version=True; actions.append(('version',None)); i+=1; continue
        if a=='-i': interactive=True; i+=1; continue
        if a=='-E': i+=1; continue
        if a.startswith('-e'):
            chunk=a[2:] if len(a)>2 else (argv[i+1] if i+1<len(argv) else None)
            if chunk is None:
                sys.stderr.write(usage(prog)); return 1
            if len(a)==2: i+=1
            actions.append(('exec',chunk)); i+=1; continue
        if a.startswith('-l'):
            name=a[2:] if len(a)>2 else (argv[i+1] if i+1<len(argv) else None)
            if name is None: sys.stderr.write(usage(prog)); return 1
            if len(a)==2: i+=1
            actions.append(('require',name)); i+=1; continue
        if a.startswith('-j'):
            cmd=a[2:] if len(a)>2 else (argv[i+1] if i+1<len(argv) else None)
            if cmd is None: sys.stderr.write(usage(prog)); return 1
            if len(a)==2: i+=1
            if cmd in ('on','off','flush'):
                actions.append(('jit',cmd))
            else:
                sys.stderr.write(f"{prog}: unknown luaJIT command or jit.* modules not installed\n"); return 1
            i+=1; continue
        if a.startswith('-O'):
            opt=a[2:]
            if opt in ('hotloop=1','+hotloop','-hotloop'):
                sys.stderr.write(f"{prog}: unknown or malformed optimization flag '{opt}'\n"); return 1
            i+=1; continue
        if a.startswith('-b'):
            sys.stderr.write(f"{prog}: unknown luaJIT command or jit.* modules not installed\n"); return 1
        sys.stderr.write(usage(prog)); return 1
    # arg table is available to LUA_INIT and chunks.
    I.globals.rawset('arg', build_arg_table(argv, script_index, script_name))
    try:
        if not ignore_env and os.environ.get('LUA_INIT'):
            init=os.environ.get('LUA_INIT')
            if init.startswith('@'):
                fn=init[1:]; I.run_chunk(open(fn,'r',encoding='latin1').read(), fn)
            else: I.run_chunk(init,'=(LUA_INIT)')
        for typ,val in actions:
            if typ=='version': sys.stdout.write(VERSION_LINE+'\n')
            elif typ=='exec': I.run_chunk(val,'(command line)')
            elif typ=='require': I.call(I.globals.rawget('require'),[val])
            elif typ=='jit':
                if val=='on': I.jit_on=True
                elif val=='off': I.jit_on=False
        if script_index is not None:
            if stdin_script: code=sys.stdin.read(); I.run_chunk(code,'stdin' if script_name!='-' else '-')
            elif script_name is not None:
                code=open(script_name,'r',encoding='latin1').read(); I.run_chunk(code,script_name)
        elif not actions and not interactive:
            if not sys.stdin.isatty():
                code=sys.stdin.read()
                if code: I.run_chunk(code,'stdin')
            else: interactive=True
        if interactive: run_repl(I)
        return 0
    except LuaExit as e:
        return e.code
    except LuaError as e:
        sys.stderr.write(I.format_error(e)+'\n'); return 1
    except OSError as e:
        sys.stderr.write(f"{prog}: cannot open {e.filename}: {e.strerror}\n"); return 1

if __name__=='__main__':
    sys.exit(execute_main(sys.argv))
