        self.os_table=make_os_lib(self); setg('os',self.os_table)
        self.coroutine_table=make_coroutine_lib(self); setg('coroutine',self.coroutine_table)
        self.debug_table=make_debug_lib(self); setg('debug',self.debug_table)
        self.bit_table=make_bit_lib(self); setg('bit',self.bit_table)
        self.jit_table=make_jit_lib(self); setg('jit',self.jit_table)
        self.file_methods=make_file_methods(self)
        self.io_table=make_io_lib(self); setg('io',self.io_table)
        self.package_table=make_package_lib(self); setg('package',self.package_table)
        # package.loaded setup
        loaded=self.package_table.rawget('loaded')
