    if isinstance(f,LuaFunction) and isinstance(env,LuaTable): f.env_table=env
    return [f]
def b_loadstring(I,args):
    code=arg(args,0,''); name=arg(args,1,'=(loadstring)')
    try:
        body=Parser(str(code)).parse(); return [LuaFunction([],True,body,I.base_env,name,1)]
    except LuaSyntax as e: return [nil, "%s:%d: %s"%(name,e.line,e.msg)]
def b_load(I,args):
    src=arg(args,0)
