        name='=stdin' if fn is nil else '@'+str(fn)
        body=Parser(data).parse(); return [LuaFunction([],True,body,I.base_env,str(fn) if fn is not nil else 'stdin',1)]
    except OSError as e: return [nil,str(e)]
    except LuaSyntax as e: return [nil,"%s:%d: %s"%(str(fn),e.line,e.msg)]
def b_dofile(I,args):
