# --- require/package ------------------------------------------------------

def make_package_lib(I):
    t=LuaTable();
    t.rawset('path', os.environ.get('LUA_PATH', DEFAULT_PATH) if not I.ignore_env else DEFAULT_PATH)
    t.rawset('cpath', os.environ.get('LUA_CPATH', DEFAULT_CPATH) if not I.ignore_env else DEFAULT_CPATH)
    t.rawset('config', PACKAGE_CONFIG); t.rawset('loaded',LuaTable()); t.rawset('preload',LuaTable())
    loaders=LuaTable(); loaders.rawset(1,BuiltinFunction('preload loader',pkg_loader_preload)); loaders.rawset(2,BuiltinFunction('Lua loader',pkg_loader_lua)); loaders.rawset(3,BuiltinFunction('C loader',pkg_loader_c)); loaders.rawset(4,BuiltinFunction('C root loader',pkg_loader_croot)); t.rawset('loaders',loaders)
    t.rawset('loadlib',BuiltinFunction('package.loadlib',lambda I,args:[nil,'dynamic libraries not enabled']))
    t.rawset('seeall',BuiltinFunction('package.seeall',pkg_seeall))
    t.rawset('searchpath',BuiltinFunction('package.searchpath',pkg_searchpath))
    return t

def pkg_seeall(I,args):
    mod=arg(args,0)
    if isinstance(mod,LuaTable):
        mt=mod.metatable or LuaTable(); mt.rawset('__index',I.globals); mod.metatable=mt
    return []

def search_lua_path(name,path):
    mod=name.replace('.', '/')
    tried=[]
    for templ in str(path).split(';'):
        fn=templ.replace('?',mod)
        if os.path.exists(fn): return fn,tried
        tried.append("\n\tno file '%s'"%fn)
    return None,tried

def pkg_searchpath(I,args):
    name=arg(args,0); path=arg(args,1,DEFAULT_PATH); sep=arg(args,2,'.'); rep=arg(args,3,os.sep)
    mod=str(name).replace(str(sep),str(rep)); tried=[]
    for templ in str(path).split(';'):
        fn=templ.replace('?',mod)
        if os.path.exists(fn): return [fn]
        tried.append("\n\tno file '%s'"%fn)
    return [nil,''.join(tried)]

def pkg_loader_preload(I,args):
    name=arg(args,0); f=I.package_table.rawget('preload').rawget(name)
    if f is not nil: return [f]
    return ["\n\tno field package.preload['%s']"%name]

def pkg_loader_lua(I,args):
    name=arg(args,0); fn,tried=search_lua_path(name,I.package_table.rawget('path'))
    if fn:
        lf=first(b_loadfile(I,[fn])); return [lf,fn]
    return [''.join(tried)]

def pkg_loader_c(I,args): return ["\n\tno file './%s.so'"%str(arg(args,0)).replace('.','/')]
def pkg_loader_croot(I,args): return ["\n\tno file './%s.so'"%str(arg(args,0)).split('.')[0]]

def b_require(I,args):
    name=arg(args,0)
    loaded=I.package_table.rawget('loaded')
    cur=loaded.rawget(name)
    if cur is not nil: return [cur]
    # built-in ffi is loaded lazily
    if name=='ffi':
        ffi=make_ffi_lib(I); loaded.rawset('ffi',ffi); return [ffi]
    msgs=[]; loaders=I.package_table.rawget('loaders')
    i=1
    while True:
        loader=loaders.rawget(i)
        if loader is nil: break
        res=I.call(loader,[name])
        f=res[0] if res else nil
        if isinstance(f,(LuaFunction,BuiltinFunction)):
            out=I.call(f,[name, res[1] if len(res)>1 else nil])
            val=out[0] if out else nil
            if val is nil:
                if loaded.rawget(name) is nil: loaded.rawset(name,True)
            else: loaded.rawset(name,val)
            return [loaded.rawget(name)]
        elif isinstance(f,str): msgs.append(f)
        i+=1
    raise LuaError("module '%s' not found:%s"%(name,''.join(msgs)), I.current_line,I.current_source)

# --- string library -------------------------------------------------------

