def lua_pattern_to_re(pat):
    i=0; out=''; n=len(pat)
    def cls(c):
        mp={'a':'A-Za-z','d':'0-9','s':'\\s','w':'A-Za-z0-9_','l':'a-z','u':'A-Z','x':'A-Fa-f0-9','p':'^A-Za-z0-9_\\s','c':'\\x00-\\x1f','z':'\\x00'}
        if c in mp: return '['+mp[c]+']'
        if c.upper()==c and c.lower() in mp:
            base=mp[c.lower()]
            return '[^'+base[1:-1]+']' if base.startswith('[') else '[^'+base+']'
        return re.escape(c)
    while i<n:
        c=pat[i]
        if c=='%':
            i+=1
            if i>=n: out+='%'; break
            out+=cls(pat[i])
        elif c in '.^$*+?-':
            if c=='.': out+='.'
            elif c=='-': out+='*?'
            else: out+=c
        elif c in '()': out+=c
        elif c=='[':
            j=i+1; content=''
            if j<n and pat[j]=='^': content+='^'; j+=1
            while j<n and pat[j]!=']':
                if pat[j]=='%' and j+1<n:
                    j+=1; cc=pat[j]
                    if cc=='d': content+='0-9'
                    elif cc=='a': content+='A-Za-z'
                    elif cc=='w': content+='A-Za-z0-9_'
                    elif cc=='s': content+='\\s'
                    else: content+=re.escape(cc)
                else: content+=re.escape(pat[j]) if pat[j] in '\\]' else pat[j]
                j+=1
            out+='['+content+']'; i=j
        else: out+=re.escape(c)
        i+=1
    return out

def do_match(s,pat,start=1):
    flags=re.S
    anchored=pat.startswith('^')
    regex=lua_pattern_to_re(pat)
    try: r=re.compile(regex,flags)
    except Exception: r=re.compile(re.escape(pat),flags)
    pos=max(0,start-1)
    return r.match(s,pos) if anchored else r.search(s,pos)

