def file_read_one(f,fmt):
    check_file(f)
    if fmt is nil: fmt='*l'
    if is_num(fmt):
        data=f.f.read(int(fmt)); return data if data!='' else nil
    fmt=str(fmt)
    if fmt in ('*a','a'): data=f.f.read(); return data
    if fmt in ('*l','l'):
        line=f.f.readline()
        if line=='': return nil
        return line[:-1] if line.endswith('\n') else line
    if fmt in ('*n','n'):
        s='';
        while True:
            c=f.f.read(1)
            if c=='' or not c.isspace(): break
        while c and (c.isdigit() or c in '+-.eE'):
            s+=c; c=f.f.read(1)
        if c: f.f.seek(f.f.tell()-1)
        n=parse_lua_number(s,silent=True); return n if n is not None else nil
    return nil

